<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Нужно ли допсоглашение для перевода цены в фиксированную?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Перевод ориентировочной цены в фиксированную оформляют дополнительным соглашением к контракту на основании согласованных РКМ. Устно или автоматически цена не фиксируется — нужно подписанное сторонами допсоглашение с новой ценой и основанием."}}, {"@type": "Question", "name": "Штраф считается от цены этапа или всего контракта?", "acceptedAnswer": {"@type": "Answer", "text": "По 44-ФЗ база для штрафа — цена контракта, а если выделены этапы, то цена соответствующего этапа. Размеры штрафов фиксированные (Постановление № 1042); пеня начисляется от цены за вычетом стоимости исполненного."}}, {"@type": "Question", "name": "Как перевести ПКИ из ориентировочной цены в фиксированную?", "acceptedAnswer": {"@type": "Answer", "text": "Стоимость покупных комплектующих изделий (ПКИ) уточняют по фактическим затратам: её подтверждают договорами с поставщиками, первичными документами и расчётно-калькуляционными материалами. Если ПКИ закупаются у соисполнителей по их контрактам ГОЗ, фиксированная цена ПКИ формируется в их звене кооперации, а головной исполнитель отражает фактическую цену."}}, {"@type": "Question", "name": "Что такое ориентировочная цена по ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Это временная (уточняемая) цена контракта, которую применяют, когда на момент заключения рассчитать фиксированную цену нельзя. В ходе исполнения её обязаны перевести в фиксированную по фактическим затратам."}}, {"@type": "Question", "name": "Обязательно ли переводить ориентировочную цену в фиксированную?", "acceptedAnswer": {"@type": "Answer", "text": "Да. При наличии данных для расчёта фиксированной цены перевод обязателен — этого требует Закон № 275-ФЗ. Отказаться от перевода нельзя."}}, {"@type": "Question", "name": "В какой срок устанавливают фиксированную цену?", "acceptedAnswer": {"@type": "Answer", "text": "По Постановлению № 1465 — не позднее чем за 2 месяца до окончания поставки продукции или завершения отдельного этапа. Для ремонта и сервиса с неопределённым объёмом — не позднее 2 месяцев после определения фактического объёма."}}, {"@type": "Question", "name": "Сколько заказчик рассматривает обращение о переводе цены?", "acceptedAnswer": {"@type": "Answer", "text": "20 рабочих дней со дня получения обращения и пакета документов."}}, {"@type": "Question", "name": "Какие документы нужны для перевода цены?", "acceptedAnswer": {"@type": "Answer", "text": "Расчётно-калькуляционные материалы (РКМ) по данным раздельного учёта, обоснование затрат и расчёт прибыли по нормативам, сведения о включении продукции в федеральный каталог. Цену закрепляют дополнительным соглашением."}}, {"@type": "Question", "name": "Какой акт регулирует перевод цены?", "acceptedAnswer": {"@type": "Answer", "text": "Постановление Правительства РФ от 02.12.2017 № 1465 о государственном регулировании цен на продукцию ГОЗ и Федеральный закон № 275-ФЗ. С 2024 года действуют изменения, внесённые Законом № 555-ФЗ (федеральный каталог продукции)."}}, {"@type": "Question", "name": "Что грозит за нарушение порядка ценообразования?", "acceptedAnswer": {"@type": "Answer", "text": "Административные штрафы по КоАП (ст. 14.55 и смежные), отказ ФАС в госрегистрации цены, а также риск не получить оплату по разнице между ориентировочной и фиксированной ценой."}}, {"@type": "Question", "name": "Как перевод цены связан с раздельным учётом?", "acceptedAnswer": {"@type": "Answer", "text": "Напрямую: РКМ для фиксированной цены формируются по данным раздельного учёта. Те же документы казначейство проверяет при санкционировании платежей, поэтому чистый раздельный учёт упрощает и перевод цены, и сопровождение."}}, {"@type": "Question", "name": "Чем перевод цены отличается от изменения цены контракта?", "acceptedAnswer": {"@type": "Answer", "text": "Перевод заложен в контракт изначально: стороны договорились, что цена временная и будет уточнена по факту. Это исполнение согласованного механизма, а не пересмотр условий. Изменение цены — правка существенного условия, допустимая лишь в ограниченных случаях."}}, {"@type": "Question", "name": "Можно ли отказаться от перевода ориентировочной цены?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. При наличии данных для расчёта фиксированной цены перевод обязателен по 275-ФЗ. Затягивание создаёт риск отказа заказчика оплачивать разницу и претензий со стороны ФАС."}}]}
